import { spawnSync } from "node:child_process"
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs"
import { join, basename, dirname } from "node:path"

const TAIL = 2000
const ORDER = ["test", "lint", "typecheck"]
export const GREEN_CAP = 3

export function runGates({ cwd, only, expect = "pass", phase, timeoutMs = 600000 }) {
  const cfgPath = join(cwd, "commitar.json")
  if (!existsSync(cfgPath)) return { passed: false, error: "commitar.json not found", results: [] }
  let cfg
  try { cfg = JSON.parse(readFileSync(cfgPath, "utf8")) } catch (e) { return { passed: false, error: `commitar.json invalid: ${e.message}`, results: [] } }
  const declared = cfg.gates ?? {}
  const names = (only?.length ? only : ORDER.concat(Object.keys(declared).filter((k) => !ORDER.includes(k)))).filter((n) => n in declared || n === "test")
  const results = names.map((name) => {
    const command = declared[name]
    if (!command) return { name, command: null, exitCode: null, ok: false, output: `gate "${name}" is not declared in commitar.json` }
    const { NODE_TEST_CONTEXT, ...env } = process.env // else a nested `node --test` changes its output format
    const r = spawnSync(command, { cwd, shell: true, encoding: "utf8", timeout: timeoutMs, env })
    const exitCode = r.error ? -1 : r.status
    const full = `${r.stdout ?? ""}${r.stderr ?? ""}${r.error ? r.error.message : ""}`.trim()
    let ok = expect === "fail" ? exitCode !== 0 : exitCode === 0
    let note = ""
    if (expect === "fail" && ok && name === "test") {
      const c = classifyRed(full, cwd)
      if (!c.ok) { ok = false; note = `RED REJECTED: ${c.reason}\n` }
    }
    return { name, command, exitCode, ok, totals: testTotals(full), output: (note + full.slice(-TAIL)).slice(0, TAIL + note.length) }
  })
  const passed = results.length > 0 && results.every((r) => r.ok)
  const greenFailures = phase ? countGreenFailures(cwd, phase, passed) : 0
  const capReached = greenFailures >= GREEN_CAP
  if (phase) writeHandoff(cwd, cfg, phase, results, passed, capReached ? capMessage(greenFailures) : null)
  return { passed, expect, results, greenFailures, capReached }
}

const capMessage = (n) => `RETRY CAP REACHED (${n} failed GREEN runs in a row): stop now, report the failing tests and why to the user, and do not keep editing.`

// Consecutive failed GREEN runs, kept in .commitar/green_failures (untracked, not part of HANDOFF.json).
// A passing GREEN run, or a run of any other phase, resets it. Only GREEN counts: RED is expected to fail.
function countGreenFailures(cwd, phase, passed) {
  const path = join(cwd, ".commitar", "green_failures")
  let n = 0
  try { n = Number.parseInt(readFileSync(path, "utf8"), 10) || 0 } catch {}
  n = phase === "GREEN" && !passed ? n + 1 : 0
  try {
    mkdirSync(dirname(path), { recursive: true })
    writeFileSync(path, `${n}\n`)
  } catch {}
  return n
}

const NEXT = {
  SPEC: "Write failing tests from the spec (RED).",
  RED: "Implement the smallest change that makes the tests pass (GREEN).",
  GREEN: "Run the AUDIT gates and review the diff.",
  AUDIT: "Commit the work (COMMIT).",
  COMMIT: "Review the result and continue in paid commitar.",
}

function git(cwd, args) {
  const r = spawnSync("git", args, { cwd, encoding: "utf8" })
  return r.status === 0 && !r.error ? r.stdout.trim() : null
}

// Commits made since the first handoff write. The baseline lives in .commitar/base (untracked).
function commitsSince(cwd) {
  const head = git(cwd, ["rev-parse", "HEAD"])
  const basePath = join(cwd, ".commitar", "base")
  let base
  try { base = readFileSync(basePath, "utf8").trim() } catch {
    if (git(cwd, ["rev-parse", "--git-dir"]) === null) return undefined
    base = head ?? ""
    mkdirSync(dirname(basePath), { recursive: true })
    writeFileSync(basePath, base + "\n")
  }
  if (head === null) return []
  const list = git(cwd, ["log", "--reverse", "--pretty=%h", base ? `${base}..HEAD` : "HEAD"])
  return list ? list.split("\n").filter(Boolean) : []
}

// RED must fail because tests fail, or because the implementation does not exist yet. Anything else
// (syntax error, bad import such as `expect` from node:test) is a broken test file. Only node:test
// output is classified; other runners keep the plain non-zero-exit rule.
export function classifyRed(out, cwd) {
  if (!/^ℹ tests \d+/m.test(out)) return classifyVitestRed(out, cwd)
  const fails = [...out.matchAll(/^\s*✖ (.+?) \(\d[\d.]*m?s\)/gm)].map((m) => m[1])
  const isFile = (n) => /\.(?:[cm]?[jt]s|[jt]sx)$/.test(n)
  const fileFails = fails.filter(isFile)
  const testFails = fails.filter((n) => !isFile(n))
  if (!fails.length) return { ok: false, reason: "the runner exited non-zero but reported no failing test" }
  if (fileFails.length) {
    const missingImpl = (out.match(/Cannot find module '([^']+)'/g) ?? []).every((m) => {
      const spec = /'([^']+)'/.exec(m)[1]
      return /^\.{1,2}\//.test(spec) || (spec.startsWith("/") && spec.startsWith(cwd) && !spec.includes("node_modules"))
    })
    const exportsOk = (out.match(/The requested module '([^']+)' does not provide an export named/g) ?? []).every((m) => /'\.{1,2}\//.test(m))
    const otherErrors = /SyntaxError|ReferenceError|TypeError|Cannot find package/.test(out.replace(/^\s*at .*$/gm, "").replace(/SyntaxError: The requested module '[^']+' does not provide an export named .*/g, "")) && !testFails.length
    const loadOk = /ERR_MODULE_NOT_FOUND|MODULE_NOT_FOUND|does not provide an export/.test(out) && missingImpl && exportsOk && !otherErrors
    if (!loadOk) return { ok: false, reason: `test file(s) failed to load for a reason other than a missing implementation (${fileFails.join(", ")}); fix the test file` }
  }
  return { ok: true }
}

// Test totals from node:test's summary lines, so the report quotes counts the runner printed. Other runners: null.
export function testTotals(out) {
  const v = /^\s*Tests\s+(.+?)\s+\((\d+)\)\s*$/m.exec(out)
  if (v) {
    const part = (k) => { const m = new RegExp(`(\\d+) ${k}`).exec(v[1]); return m ? Number(m[1]) : 0 }
    return { tests: Number(v[2]), pass: part("passed"), fail: part("failed") }
  }
  const py = pytestTotals(out)
  if (py) return py
  const n = (k) => { const m = new RegExp(`^ℹ ${k} (\\d+)\\s*$`, "m").exec(out); return m ? Number(m[1]) : null }
  const tests = n("tests"), pass = n("pass"), fail = n("fail")
  return tests === null || pass === null || fail === null ? null : { tests, pass, fail }
}

// vitest: a file-level failure prints `FAIL  <file> [ <file> ]` followed by the error. It is an acceptable RED only when the
// error is a missing module that is relative or under the project; a parse failure or any other load error is a broken test file.
// A run without test files (`No test files found`) is not a RED either. Output that is not vitest's keeps the plain non-zero rule.
function classifyVitestRed(out, cwd) {
  if (/^\s*No test files found/m.test(out)) return { ok: false, reason: "vitest found no test files; RED needs new failing tests" }
  if (!/^\s*Test Files\s+\d+/m.test(out)) return classifyPytestRed(out, cwd)
  const fileFails = [...out.matchAll(/^\s*FAIL\s+(\S+)\s+\[ \1 \]/gm)].map((m) => m[1])
  const testFails = /^\s*FAIL\s+\S+\s+>\s/m.test(out)
  if (!fileFails.length && !testFails) return { ok: false, reason: "the runner exited non-zero but reported no failing test" }
  if (fileFails.length) {
    const body = out.replace(/^\s*at .*$/gm, "")
    const missing = [...body.matchAll(/Cannot find module '([^']+)'/g)].map((m) => m[1])
    const relOrProject = (spec) => /^\.{1,2}\//.test(spec) || (spec.startsWith("/") && spec.startsWith(cwd) && !spec.includes("node_modules"))
    const otherErrors = /Parse failure|SyntaxError|ReferenceError|TypeError|Failed to resolve import|Cannot find package/.test(body)
    if (!missing.length || !missing.every(relOrProject) || otherErrors) {
      return { ok: false, reason: `test file(s) failed to load for a reason other than a missing implementation (${fileFails.join(", ")}); fix the test file` }
    }
  }
  return { ok: true }
}

// pytest: the last line is a summary such as `1 failed, 1 passed in 0.01s` (quiet) or `=== 2 passed in 0.00s ===`.
const PYTEST_SUMMARY = /^(?:=+ )?((?:\d+ (?:passed|failed|errors?|skipped|xfailed|xpassed|deselected|warnings?)(?:, )?)+|no tests ran) in [\d.]+s(?: \(.+\))?(?: =+)?\s*$/m

// A collection error (`ERROR collecting <file>`) is an acceptable RED only for a missing module (Python cannot tell a missing
// project module from a missing package, so any ModuleNotFoundError counts) or a missing name in a module under the project.
// A SyntaxError, any other exception and a fixture/setup error (`ERROR file::test`) mean a broken test file.
function classifyPytestRed(out, cwd) {
  if (!PYTEST_SUMMARY.test(out)) return { ok: true }
  const blocks = out.split(/^_{3,} ERROR collecting .+? _{3,}$/m).slice(1)
  if (/^ERROR \S+::\S+/m.test(out)) return { ok: false, reason: "a test failed during setup or teardown (fixture error); fix the test file" }
  const bad = []
  for (const b of blocks) {
    const errs = [...b.matchAll(/^E\s+([A-Za-z_.]*(?:Error|Exception)):\s?(.*)$/gm)].map((m) => [m[1], m[2]])
    const okBlock = errs.length > 0 && errs.every(([kind, msg]) =>
      kind === "ModuleNotFoundError" ||
      (kind === "ImportError" && /cannot import name '.+' from '.+' \((.+?)\)/.test(msg) && (() => { const f = /\((.+?)\)\s*$/.exec(msg)?.[1] ?? ""; return f.startsWith(cwd) && !f.includes("site-packages") })()))
    if (!okBlock) bad.push(errs.map(([k]) => k).join(",") || "unknown error")
  }
  if (bad.length) return { ok: false, reason: `test file(s) failed to collect for a reason other than a missing implementation (${bad.join("; ")}); fix the test file` }
  if (/^no tests ran in /m.test(out) || /^=* ?no tests ran in /m.test(out)) return { ok: false, reason: "pytest ran no tests; RED needs new failing tests" }
  if (!blocks.length && !/^FAILED /m.test(out)) return { ok: false, reason: "the runner exited non-zero but reported no failing test" }
  return { ok: true }
}

function pytestTotals(out) {
  const m = PYTEST_SUMMARY.exec(out)
  if (!m || m[1] === "no tests ran") return null
  const c = {}
  for (const [, n, k] of m[1].matchAll(/(\d+) (passed|failed|errors?|skipped|xfailed|xpassed)/g)) c[k.replace(/s$/, "")] = Number(n)
  const g = (k) => c[k] ?? 0
  const tests = g("passed") + g("failed") + g("error") + g("skipped") + g("xfailed") + g("xpassed")
  return { tests, pass: g("passed"), fail: g("failed") + g("error") }
}

function writeHandoff(cwd, cfg, phase, results, passed, capNote) {
  const path = join(cwd, "HANDOFF.json")
  let h = {}
  try { h = JSON.parse(readFileSync(path, "utf8")) } catch {}
  const commits = commitsSince(cwd)
  // Keep the latest result per phase; legacy entries without a phase are dropped.
  const gates = (h.gates ?? []).filter((g) => g.phase && g.phase !== phase)
    .concat(results.map((r) => ({ phase, command: r.command ?? r.name, passed: r.ok, output: r.output })))
  const spec = h.spec ?? cfg.spec ?? ["SPEC.md", "spec.md"].find((f) => existsSync(join(cwd, f)))
  const done = phase === "COMMIT" && passed && (commits?.length ?? 0) > 0
  h = {
    ...h, version: 1, project: h.project ?? cfg.name ?? basename(cwd), phase,
    status: passed ? (done ? "done" : "in_progress") : "gate_failed",
    gates, next: capNote ?? (passed ? (phase === "COMMIT" && !done ? "Commit the work, then re-run the COMMIT gate." : NEXT[phase]) : `Fix the failing ${phase} gate.`),
  }
  if (spec) h.spec = spec
  if (commits) h.commits = commits
  writeFileSync(path, JSON.stringify(h, null, 2) + "\n")
}

export function summarize(res) {
  if (res.error) return `GATES ERROR: ${res.error}`
  const lines = res.results.map((r) => `${r.ok ? "PASS" : "FAIL"} ${r.name} (${r.command}) exit=${r.exitCode}${r.totals ? ` tests=${r.totals.tests} pass=${r.totals.pass} fail=${r.totals.fail}` : ""}${r.ok ? "" : "\n" + r.output}`)
  const cap = res.capReached ? `\n${capMessage(res.greenFailures)}` : ""
  return `${res.passed ? "GATES PASSED" : "GATES FAILED"} (expected: ${res.expect})\n${lines.join("\n")}${cap}`
}
